392				}
393				if fd.Verdict == "below_minimum" && fixNecessityRank(fd.FixNecessity) > 0 {
394					fixed := planRefFixed(doc, fd.PlanRef)
395					e := &belowMinimumEntry{run: ri + 1, finding: fd, resolved: fixed, fixedTogether: fixed}
396					entries = append(entries, e)
397					index[[2]int{ri + 1, fd.ID}] = e
398				}
399			}
400		}
401		return entries
402	}
403	
404	// planRefFixed は、plan_ref の問題が直ったか (状態が done か done-external か) を返す。問題がまだ
405	// 直っていないか、直さないと決めた (not-fixed) なら、指摘の箇所も直っていない。参照の実在は別に検査する。
406	func planRefFixed(doc *recordDoc, ref *recordPlanRef) bool {
407		if ref == nil || ref.Run < 1 || ref.Run > len(doc.Runs) {
408			return false
409		}
410		for _, pl := range doc.Runs[ref.Run-1].Plans {
411			if pl.ProblemID == ref.Problem {
412				return pl.Status == "done" || pl.Status == "done-external"
413			}
414		}
415		return false
416	}
417	
418	// renderBelowMinimumSection は節「下限未満の指摘」を書く。記録に下限未満の指摘が 1 件も
419	// 無ければ何も書かない。並べるのは残っている指摘だけで、必要度ごとの表にする。
420	// 件数はここで数え、人が書いた集計をどこからも読まない (推移の表と同じ)。
421	func renderBelowMinimumSection(b *strings.Builder, doc *recordDoc) {
422		hasBelowMinimum := false
423		for _, run := range doc.Runs {
424			for _, fd := range run.Findings {
425				if fd.Verdict == "below_minimum" {
426					hasBelowMinimum = true
427				}
428			}
429		}
430		if !hasBelowMinimum {
431			return
432		}
433		b.WriteString("\n## 下限未満の指摘\n")
434		entries := belowMinimumEntries(doc, len(doc.Runs))
435		remaining := 0
436		for _, necessity := range []string{"must", "should", "could"} {
437			var rows []*belowMinimumEntry
438			for _, e := range entries {
439				if !e.resolved && e.finding.FixNecessity == necessity {
440					rows = append(rows, e)
441				}
442			}
443			if len(rows) == 0 {
444				continue
445			}
446			remaining += len(rows)
447			fmt.Fprintf(b, "\n### %s (%d 件)\n\n", fixNecessityJa(necessity), len(rows))
448			b.WriteString("| 判定した回 | 指摘 | 回避策 | また報告された回 |\n")
449			b.WriteString("| --- | --- | --- | --- |\n")
450			for _, e := range rows {
451				b.WriteString(recordRow(renderBelowMinimumCells(e)))
452			}
453		}
454		if remaining == 0 {
455			b.WriteString("\n残っている下限未満の指摘はありません (後の回で判定し直したか、採択にしたか、採択した問題と一緒に直した)。\n")
456		}
457	}
458	
459	// renderBelowMinimumCells は節「下限未満の指摘」の 1 行のセルのスライスを返す。
460	func renderBelowMinimumCells(e *belowMinimumEntry) []string {
461		fd := e.finding
462		loc := fd.File
463		if fd.Line > 0 {
464			loc = fmt.Sprintf("%s:%d", fd.File, fd.Line)
465		}
466		// 回避策は、条件 2 を判定した指摘 (Should) だけが持つ。条件 1 が成り立つ指摘 (Could) は
467		// 何もしなくても目的を達成できるので、回避策を書かない。
468		workaround := "—"
469		if r := fd.FixNecessityReason; r != nil && r.WorkaroundReason != "" {
470			workaround = recordCell(r.WorkaroundReason)
471		}
472		reported := "—"
473		if len(e.reported) > 0 {
474			reported = strings.Join(e.reported, "、")
475		}
476		return []string{
477			fmt.Sprintf("%d 回目 #%d", e.run, fd.ID),
478			"`" + recordCell(loc) + "` " + recordCell(fd.Summary),
479			workaround,
480			reported,
481		}
482	}
483	
484	// renderFixNecessityNote は、判定セルに添える必要度と、下限未満の指摘の参照を返す。
485	// どちらも無い指摘では空。過去の記録の判定セルを変えないため。
486	func renderFixNecessityNote(fd recordFinding) string {
487		var note string
488		if fd.FixNecessityReason != nil {
489			necessity := "決められない"

